/**
 * Integration test: `keyboard/handler-missing` per-finding confidence
 * downgrade when the rule fires inside a file the response also surfaces
 * under `meta.scannedBuildArtifacts`.
 *
 * Doctrine source: docs/kb/architecture/ai-first-consumer.md
 *   "Per-finding confidence must reflect per-rule coverage limitations."
 *   The per-FILE axis (sibling of the per-RULE pass): when a finding
 *   inside a build-artifact file ships at `confidence: "high"` next to
 *   a `scannedBuildArtifacts` entry that classifies the same file as
 *   generated bytes, the response disagrees with itself silently. The
 *   enricher routes through `enrichFindingsWithBuildArtifactPath`
 *   downstream of the per-rule limitation pass.
 *
 * Fixture shape: a minimal minified-JS bundle (`.min.` infix → the
 * deterministic `definite-min-infix` build-artifact classification)
 * containing the canonical click-attach-without-keyboard-sibling
 * pattern that the rule's external-JS handler grammar fires on. The
 * grammar is `<ident>.addEventListener('click', …)` followed by no
 * paired `keydown`/`keyup` for the same `ident` — vanilla-JS apps and
 * jQuery-shaped delegation bundles routinely show this pattern after
 * minification, but the framework's actual keyboard wiring lives in a
 * document-level event-delegation table the rule cannot see.
 *
 * Pinned downstream behavior: the per-finding entry inside the .min.js
 * file ships at `confidence: "low"` AND its `couldBeWrongBecause`
 * contains `fired_inside_bundled_js_likely_framework_event_delegation`.
 * Without the enricher, the finding rides at `confidence: "high"`
 * (severity-derived) with no caveat — exactly the contradictory shape
 * the doctrine names.
 */

import { describe, expect, it } from "bun:test";
import { type ParsedFile, runScan } from "../../src/engine/scanner.ts";
import { parseTsx } from "../../src/input/parsers/index.ts";
import { assembleScanFamilyResponse } from "../../src/mcp/response-assembler.ts";
import { BUILTIN_RULES } from "../../src/rules/index.ts";
import { wcag22 } from "../../src/standards/wcag22/standard.ts";
import type { Ast } from "../../src/types/ast.ts";

function jsFile(path: string, source: string): ParsedFile {
  const parsed = parseTsx(source);
  const ast: Ast = { language: "js", root: parsed.root, errors: parsed.errors };
  return { filePath: path, source, ast };
}

describe("keyboard/handler-missing per-finding confidence on bundled JS", () => {
  it("downgrades confidence to low and attaches the bundled-JS reason on a .min.js file in scannedBuildArtifacts", () => {
    // Minimal minified-JS bundle: `.min.` infix triggers the
    // `definite-min-infix` build-artifact classification, and the
    // body has a click attach with no paired keyboard sibling.
    // Single-line shape mirrors a real minified distribution; the rule's
    // external-JS handler grammar fires on the addEventListener('click',…)
    // call without a same-file `keydown`/`keyup` for `el`.
    const minifiedJs = `(function(){var el=document.querySelector('.btn');el.addEventListener('click',function(){doit()});})();`;
    const path = "vendor/widget-1.2.3.min.js";
    const files = [jsFile(path, minifiedJs)];

    const { result, perRuleCoverage } = runScan({
      standards: [wcag22],
      rules: BUILTIN_RULES,
      enabled: ["wcag22"],
      files,
    });

    const response = assembleScanFamilyResponse({
      violations: result.violations,
      rawViolations: result.violations,
      parsedFiles: files,
      activeRules: BUILTIN_RULES,
      durationMs: result.durationMs,
      enabledStandards: result.enabledStandards,
      perRuleCoverage,
      reviewCandidates: [],
      wrappers: {
        wrappers: [],
        sessionOnly: [],
        bySource: {
          fromConfig: [],
          fromSession: [],
          fromAutoDetect: { confirmed: [], assumed: [] },
        },
        elements: {},
      },
      unusedWrappers: [],
      suppressions: [],
      verboseMeta: true,
      preset: undefined,
      actionableManual: 0,
      untargetedCriteria: 0,
      configSource: null,
      rootSource: "explicit",
    });

    const file = response.files.find((f) => f.path === path);
    expect(file).toBeDefined();
    const finding = file!.findings.find((v) => v.ruleId === "keyboard/handler-missing");
    // Sanity: the rule must actually have fired on the fixture — without
    // the finding the confidence assertion below would be vacuous.
    expect(finding).toBeDefined();
    expect(finding!.confidence).toBe("low");
    expect(finding!.couldBeWrongBecause).toContain(
      "fired_inside_bundled_js_likely_framework_event_delegation",
    );
  });

  it("does NOT downgrade keyboard/handler-missing on an authored .js file (no build-artifact classification, no enrichment)", () => {
    // Same handler shape, but on a file whose path does NOT match any
    // build-artifact predicate. The rule's per-rule
    // `coverageConfidence` may still be `"medium"` (crossFileCapable:
    // false → cross_file_listener_resolution_not_attempted_by_rule), but
    // that's the per-RULE axis handled by `per-finding-confidence-parity`;
    // the per-FILE downgrade should NOT fire here.
    const authoredJs = `var el = document.querySelector('.btn');\nel.addEventListener('click', function () { doit(); });\n`;
    const path = "src/widget.js";
    const files = [jsFile(path, authoredJs)];

    const { result, perRuleCoverage } = runScan({
      standards: [wcag22],
      rules: BUILTIN_RULES,
      enabled: ["wcag22"],
      files,
    });

    const response = assembleScanFamilyResponse({
      violations: result.violations,
      rawViolations: result.violations,
      parsedFiles: files,
      activeRules: BUILTIN_RULES,
      durationMs: result.durationMs,
      enabledStandards: result.enabledStandards,
      perRuleCoverage,
      reviewCandidates: [],
      wrappers: {
        wrappers: [],
        sessionOnly: [],
        bySource: {
          fromConfig: [],
          fromSession: [],
          fromAutoDetect: { confirmed: [], assumed: [] },
        },
        elements: {},
      },
      unusedWrappers: [],
      suppressions: [],
      verboseMeta: true,
      preset: undefined,
      actionableManual: 0,
      untargetedCriteria: 0,
      configSource: null,
      rootSource: "explicit",
    });

    const file = response.files.find((f) => f.path === path);
    expect(file).toBeDefined();
    const finding = file!.findings.find((v) => v.ruleId === "keyboard/handler-missing");
    expect(finding).toBeDefined();
    // The per-FILE bundled-JS code MUST NOT be present — this file is
    // authored, not a build artifact. Per-RULE codes from the
    // crossFileCapable axis may still ride along; we assert ONLY the
    // bundled-JS code is absent.
    expect(finding!.couldBeWrongBecause ?? []).not.toContain(
      "fired_inside_bundled_js_likely_framework_event_delegation",
    );
  });
});
